// Bells, beeps and the rest buzzer are synthesized with Web Audio. The spoken
// countdown uses short clips in public/voice/, generated by scripts/gen-voice.py.
// With "My voice", the user's own recordings from the recorder page replace
// those, follow the work bell / rest buzzer, and add a spoken "done" at the end. The
// cougar roar and growl that close a workout are one clip, public/sounds/roar.mp3.
import type { CountdownStyle, SoundKind } from './engine';
import { loadClips, watchClips, type VoiceClips } from './voiceStore';

let ctx: AudioContext | null = null;
// Limiter in front of the speakers so stacked partials can be loud without clipping.
let out: AudioNode | null = null;

const VOICE_FILES = ['three', 'two', 'one'] as const;
const COUNTDOWN_CLIPS: Record<number, string> = { 3: 'three', 2: 'two', 1: 'one' };
const voice = new Map<string, AudioBuffer>();
const mine = new Map<string, AudioBuffer>();
let roar: AudioBuffer | undefined;
let voiceLoading = false;

/** Must first be called from a user gesture (e.g. the Start click). */
export function unlockAudio(): void {
  if (!ctx) {
    ctx = new AudioContext();
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -6;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.001;
    limiter.release.value = 0.1;
    limiter.connect(ctx.destination);
    out = limiter;
  }
  if (ctx.state === 'suspended') void ctx.resume();
  if (!voiceLoading) {
    voiceLoading = true;
    void loadVoice(ctx);
    void loadRoar(ctx);
    const audio = ctx;
    void loadClips().then((clips) => loadMine(audio, clips));
    watchClips((clips) => void loadMine(audio, clips));
  }
}

async function loadMine(audio: AudioContext, clips: VoiceClips): Promise<void> {
  mine.clear();
  await Promise.all(
    Object.entries(clips).map(async ([name, url]) => {
      try {
        const res = await fetch(url!);
        mine.set(name, await audio.decodeAudioData(await res.arrayBuffer()));
      } catch (err) {
        console.warn(`recorded clip ${name} failed to load`, err);
      }
    }),
  );
}

async function loadVoice(audio: AudioContext): Promise<void> {
  await Promise.all(
    VOICE_FILES.map(async (name) => {
      try {
        const res = await fetch(`voice/${name}.mp3`);
        voice.set(name, await audio.decodeAudioData(await res.arrayBuffer()));
      } catch (err) {
        // Missing clip: playCountdown falls back to the beep.
        console.warn(`voice clip ${name} failed to load`, err);
      }
    }),
  );
}

async function loadRoar(audio: AudioContext): Promise<void> {
  try {
    const res = await fetch('sounds/roar.mp3');
    roar = await audio.decodeAudioData(await res.arrayBuffer());
  } catch (err) {
    // Missing clip: the workout ends without a roar.
    console.warn('roar failed to load', err);
  }
}

function tone(freq: number, duration: number, type: OscillatorType, gain: number, at = 0): void {
  if (!ctx || !out) return;
  const t0 = ctx.currentTime + at;
  const osc = ctx.createOscillator();
  const amp = ctx.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  amp.gain.setValueAtTime(gain, t0);
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
  osc.connect(amp).connect(out);
  osc.start(t0);
  osc.stop(t0 + duration);
}

/** Plays a clip `at` seconds from now; false if it isn't loaded. */
function play(clip: AudioBuffer | undefined, at = 0): boolean {
  if (!ctx || !clip) return false;
  const src = ctx.createBufferSource();
  src.buffer = clip;
  src.connect(ctx.destination);
  src.start(ctx.currentTime + at);
  return true;
}

/** Countdown cue for `second` (3, 2 or 1) seconds left. */
export function playCountdown(second: number, style: CountdownStyle): void {
  // A missing recording falls back to the stock voice, then the beep.
  if (style === 'mine' && play(mine.get(String(second)))) return;
  if (style !== 'beep' && play(voice.get(COUNTDOWN_CLIPS[second]))) return;
  tone(660, 0.12, 'sine', 0.4);
}

/**
 * Marks a work or rest start in place of the transition sound: a boxing bell
 * rung three times for work, a buzzer for rest. With "My voice", the user's
 * recorded "work" / "rest" follows once the bell or buzzer has finished.
 */
export function playAnnouncement(kind: 'work' | 'rest', style: CountdownStyle): void {
  let after: number;
  if (kind === 'work') {
    for (let i = 0; i < 3; i++) bellStrike(i * BELL_GAP);
    after = 2 * BELL_GAP + 0.45;
  } else {
    buzz(BUZZ_LENGTH);
    after = BUZZ_LENGTH + 0.1;
  }
  if (style === 'mine') play(mine.get(kind), after);
}

// Seconds between the work bell's three rings, and how long the rest buzzer lasts.
const BELL_GAP = 0.3;
const BUZZ_LENGTH = 0.9;

/** Arena-style buzzer: detuned low saws and a square, filtered so it rasps without hissing. */
function buzz(duration: number): void {
  if (!ctx || !out) return;
  const t0 = ctx.currentTime;
  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0, t0);
  amp.gain.linearRampToValueAtTime(0.22, t0 + 0.015);
  amp.gain.setValueAtTime(0.22, t0 + duration - 0.04);
  amp.gain.linearRampToValueAtTime(0, t0 + duration);
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = 2400;
  filter.connect(amp).connect(out);
  for (const [type, freq] of [
    ['sawtooth', 147],
    ['sawtooth', 149.5],
    ['square', 294],
  ] as const) {
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.value = freq;
    osc.connect(filter);
    osc.start(t0);
    osc.stop(t0 + duration);
  }
}

function bellStrike(at: number): void {
  tone(1150, 1.1, 'triangle', 0.7, at);
  tone(1150 * 2.76, 0.7, 'sine', 0.35, at);
  tone(1150 * 5.4, 0.4, 'sine', 0.2, at);
  tone(4200, 0.03, 'square', 0.25, at);
}

/** Played when a step starts. */
export function playTransition(kind: SoundKind): void {
  switch (kind) {
    case 'bell':
      // Boxing-ring double strike: a bright, high bell hit twice in quick
      // succession. Inharmonic partials read as metal; the short square click
      // gives each hit a hard attack.
      bellStrike(0);
      bellStrike(0.16);
      break;
    case 'beep':
      tone(990, 0.35, 'square', 0.2);
      break;
    case 'whistle':
      tone(2100, 0.5, 'triangle', 0.35);
      tone(2300, 0.5, 'triangle', 0.15);
      break;
  }
}

/** Played once when the workout finishes, then the user's "done" if recorded, then a cougar roar and growl. */
export function playFinish(kind: SoundKind, style: CountdownStyle): void {
  playTransition(kind);
  setTimeout(() => playTransition(kind), 450);
  setTimeout(() => playTransition(kind), 900);
  // After the third hit so the word isn't masked; there is no stock "done".
  const done = style === 'mine' ? mine.get('done') : undefined;
  play(done, 1.2);
  // The roar follows the "done" so the two don't talk over each other.
  play(roar, done ? 1.2 + done.duration + 0.2 : 1.3);
}
